CREATE TABLE "users" ("id" uuid NOT NULL,"username" varchar(100) NOT NULL,"full_name" varchar(100) NOT NULL,"password" varchar(255) NOT NULL,"is_active" boolean DEFAULT true,"is_superuser" boolean DEFAULT false,"role" varchar(20) NOT NULL,"car_park" varchar(20),"created_at" timestamptz NOT NULL,"updated_at" timestamptz,"deleted_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_users_deleted_at" ON "users" ("deleted_at");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_username" ON "users" ("username");
CREATE TABLE "user_sessions" ("id" uuid NOT NULL,"ip_address" inet,"user_agent" text,"expire_at" timestamptz NOT NULL,"revoked_at" timestamptz,"created_at" timestamptz,"user_id" uuid NOT NULL,PRIMARY KEY ("id"),CONSTRAINT "fk_user_sessions_user" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "idx_user_sessions_user_id" ON "user_sessions" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_user_sessions_revoked_at" ON "user_sessions" ("revoked_at");
CREATE INDEX IF NOT EXISTS "idx_user_sessions_expire_at" ON "user_sessions" ("expire_at");
CREATE TABLE "mac_users" ("id" bigserial,"mac_username" text NOT NULL,"mac_password" text NOT NULL,"is_active" boolean DEFAULT true,PRIMARY KEY ("id"));
CREATE TABLE "cameras" ("id" bigserial,"name" varchar(255) NOT NULL,"type" varchar(50) NOT NULL,"channel_name" varchar(255),"channel_token" varchar(255),"created_at" timestamptz NOT NULL,"updated_at" timestamptz,"deleted_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_cameras_deleted_at" ON "cameras" ("deleted_at");
CREATE TABLE "cars" ("id" bigserial,"car_number" varchar(255) NOT NULL,"owner_name" varchar(255),"is_staff" boolean DEFAULT false,"created_at" timestamptz NOT NULL,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_cars_car_number" ON "cars" ("car_number");
CREATE TABLE "car_subscriptions" ("id" bigserial,"total_payment_amount" decimal(20,8) DEFAULT '0.0',"currency" varchar(20) NOT NULL,"is_paid" boolean NOT NULL DEFAULT false,"start_time" timestamptz,"end_time" timestamptz,"is_active" boolean DEFAULT true,"revoked_at" timestamptz,"created_at" timestamptz NOT NULL,"updated_at" timestamptz,"car_id" bigint NOT NULL,PRIMARY KEY ("id"),CONSTRAINT "fk_car_subscriptions_car" FOREIGN KEY ("car_id") REFERENCES "cameras"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "idx_car_subscriptions_revoked_at" ON "car_subscriptions" ("revoked_at");
CREATE TABLE "car_sessions" ("id" bigserial,"currency" varchar(20) NOT NULL,"status" varchar(100),"reason" text,"is_paid" boolean NOT NULL DEFAULT false,"camera_token" varchar(255),"car_id" bigint NOT NULL,"camera_id" bigint NOT NULL,"total_payment_amount" decimal(20,8) DEFAULT '0.0',"start_time" timestamptz,"end_time" timestamptz,"image_url" text,"car_park" varchar(100),"duration" decimal(20,8) DEFAULT '0.0',"created_at" timestamptz NOT NULL,"updated_at" timestamptz,PRIMARY KEY ("id"),CONSTRAINT "fk_car_sessions_car" FOREIGN KEY ("car_id") REFERENCES "cars"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "fk_car_sessions_camera" FOREIGN KEY ("camera_id") REFERENCES "cameras"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "tariffs" ("id" bigserial,"name" varchar(255) NOT NULL,"duration" bigint NOT NULL,"is_active" boolean DEFAULT true,"price_amount" text,"currency" varchar(20) NOT NULL,"created_at" timestamptz NOT NULL,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_tariffs_duration" ON "tariffs" ("duration");
